changeSet.sql:

if exists(select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_NAME = 'Comment' and COLUMN_NAME = 'AssetID')
BEGIN
	delete V from CommentRelation V inner join Comment C on C.ID = V.CommentID and C.AssetID is null;
	delete V from CommentVote V inner join Comment C on C.ID = V.CommentID and C.AssetID is null;
	delete Comment where AssetID is null;
END


if exists(select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_NAME = 'Comment' and COLUMN_NAME = 'DateCreated')
BEGIN
	EXEC sp_rename 'dbo.Comment.DateCreated', 'CreatedOn', 'COLUMN';
END
if exists(select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_NAME = 'Comment' and COLUMN_NAME = 'CreatingResourceID')
BEGIN
	EXEC sp_rename 'dbo.Comment.CreatingResourceID', 'CreatedBy', 'COLUMN';
END
if exists(select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_NAME = 'Comment' and COLUMN_NAME = 'DateEdited')
BEGIN
	EXEC sp_rename 'dbo.Comment.DateEdited', 'UpdatedOn', 'COLUMN';
END
if exists(select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_NAME = 'Comment' and COLUMN_NAME = 'CommentTypeID')
BEGIN
	EXEC sp_rename 'dbo.Comment.CommentTypeID', 'CommentType', 'COLUMN';
END

changeSet.rollback:

EXEC sp_rename 'dbo.Comment.CreatedOn', 'DateCreated', 'COLUMN';
GO
EXEC sp_rename 'dbo.Comment.CreatedBy', 'CreatingResourceID', 'COLUMN';
GO
EXEC sp_rename 'dbo.Comment.UpdatedOn', 'DateEdited', 'COLUMN';
GO
EXEC sp_rename 'dbo.Comment.CommentType', 'CommentTypeID', 'COLUMN';
GO
